-- MATHEMATICS Round One (30 questions)
('nsmq_math_r1_001', 'subj_math', 'What is the value of log₁₀(1000)?', 'multiple_choice', 'round_one', '["A. 2", "B. 3", "C. 4", "D. 10"]', 'B', 'log₁₀(1000) = log₁₀(10³) = 3', 'easy', 3, 30),
('nsmq_math_r1_002', 'subj_math', 'If f(x) = 2x² - 3x + 1, what is f(2)?', 'multiple_choice', 'round_one', '["A. 3", "B. 5", "C. 7", "D. 9"]', 'A', 'f(2) = 2(4) - 3(2) + 1 = 8 - 6 + 1 = 3', 'easy', 3, 30),
('nsmq_math_r1_003', 'subj_math', 'What is the sum of the interior angles of a hexagon?', 'multiple_choice', 'round_one', '["A. 540°", "B. 720°", "C. 900°", "D. 1080°"]', 'B', 'Sum = (n-2) × 180° = (6-2) × 180° = 720°', 'easy', 3, 30),
('nsmq_math_r1_004', 'subj_math', 'Simplify: √48 + √27', 'multiple_choice', 'round_one', '["A. 5√3", "B. 7√3", "C. 9√3", "D. 11√3"]', 'B', '√48 = 4√3, √27 = 3√3, so 4√3 + 3√3 = 7√3', 'medium', 3, 30),
('nsmq_math_r1_005', 'subj_math', 'What is the derivative of sin(2x)?', 'multiple_choice', 'round_one', '["A. cos(2x)", "B. 2cos(2x)", "C. -2cos(2x)", "D. 2sin(2x)"]', 'B', 'Using chain rule: d/dx[sin(2x)] = cos(2x) × 2 = 2cos(2x)', 'medium', 3, 30),
('nsmq_math_r1_006', 'subj_math', 'If 3^x = 81, what is x?', 'multiple_choice', 'round_one', '["A. 3", "B. 4", "C. 5", "D. 6"]', 'B', '81 = 3⁴, so x = 4', 'easy', 3, 30),
('nsmq_math_r1_007', 'subj_math', 'What is the area of a circle with radius 7 cm? (Use π = 22/7)', 'multiple_choice', 'round_one', '["A. 44 cm²", "B. 154 cm²", "C. 308 cm²", "D. 616 cm²"]', 'B', 'Area = πr² = (22/7) × 7² = 22 × 7 = 154 cm²', 'easy', 3, 30),
('nsmq_math_r1_008', 'subj_math', 'Solve for x: 2x + 5 = 3x - 7', 'multiple_choice', 'round_one', '["A. 12", "B. -12", "C. 2", "D. -2"]', 'A', '5 + 7 = 3x - 2x, so x = 12', 'easy', 3, 30),
('nsmq_math_r1_009', 'subj_math', 'What is the 10th term of the arithmetic sequence 3, 7, 11, 15, ...?', 'multiple_choice', 'round_one', '["A. 35", "B. 39", "C. 43", "D. 47"]', 'B', 'a₁₀ = 3 + (10-1) × 4 = 3 + 36 = 39', 'medium', 3, 30),
('nsmq_math_r1_010', 'subj_math', 'What is the value of sin 30° + cos 60°?', 'multiple_choice', 'round_one', '["A. 0", "B. 0.5", "C. 1", "D. 1.5"]', 'C', 'sin 30° = 0.5, cos 60° = 0.5, so sum = 1', 'easy', 3, 30),
('nsmq_math_r1_011', 'subj_math', 'If the determinant of matrix [[a, b], [c, d]] is 5, what is ad - bc?', 'multiple_choice', 'round_one', '["A. -5", "B. 0", "C. 5", "D. 10"]', 'C', 'The determinant of a 2×2 matrix is ad - bc = 5', 'medium', 3, 30),
('nsmq_math_r1_012', 'subj_math', 'What is the probability of getting at least one head when tossing two coins?', 'multiple_choice', 'round_one', '["A. 1/4", "B. 1/2", "C. 3/4", "D. 1"]', 'C', 'P(at least one head) = 1 - P(no heads) = 1 - 1/4 = 3/4', 'medium', 3, 30),
('nsmq_math_r1_013', 'subj_math', 'What is the gradient of the line 3x - 4y + 12 = 0?', 'multiple_choice', 'round_one', '["A. 3/4", "B. -3/4", "C. 4/3", "D. -4/3"]', 'A', 'Rearranging: y = (3/4)x + 3, gradient = 3/4', 'medium', 3, 30),
('nsmq_math_r1_014', 'subj_math', 'Evaluate: ∫x² dx', 'multiple_choice', 'round_one', '["A. 2x + C", "B. x³ + C", "C. x³/3 + C", "D. 3x³ + C"]', 'C', '∫x² dx = x³/3 + C', 'medium', 3, 30),
('nsmq_math_r1_015', 'subj_math', 'What is the LCM of 12 and 18?', 'multiple_choice', 'round_one', '["A. 6", "B. 36", "C. 72", "D. 216"]', 'B', '12 = 2² × 3, 18 = 2 × 3², LCM = 2² × 3² = 36', 'easy', 3, 30),
('nsmq_math_r1_016', 'subj_math', 'If a:b = 2:3 and b:c = 4:5, what is a:c?', 'multiple_choice', 'round_one', '["A. 8:15", "B. 2:5", "C. 6:15", "D. 4:5"]', 'A', 'a:b:c = 8:12:15, so a:c = 8:15', 'hard', 3, 30),
('nsmq_math_r1_017', 'subj_math', 'What is the value of 5! (5 factorial)?', 'multiple_choice', 'round_one', '["A. 25", "B. 60", "C. 120", "D. 720"]', 'C', '5! = 5 × 4 × 3 × 2 × 1 = 120', 'easy', 3, 30),
('nsmq_math_r1_018', 'subj_math', 'Solve: |2x - 3| = 7', 'multiple_choice', 'round_one', '["A. x = 5 or x = -2", "B. x = 5 or x = 2", "C. x = -5 or x = -2", "D. x = 5 only"]', 'A', '2x - 3 = 7 gives x = 5; 2x - 3 = -7 gives x = -2', 'medium', 3, 30),
('nsmq_math_r1_019', 'subj_math', 'What is the sum of the first 20 positive integers?', 'multiple_choice', 'round_one', '["A. 190", "B. 200", "C. 210", "D. 220"]', 'C', 'Sum = n(n+1)/2 = 20 × 21/2 = 210', 'easy', 3, 30),
('nsmq_math_r1_020', 'subj_math', 'If cos θ = 3/5, what is sin θ? (θ is acute)', 'multiple_choice', 'round_one', '["A. 3/5", "B. 4/5", "C. 5/4", "D. 5/3"]', 'B', 'sin²θ + cos²θ = 1, sin²θ = 1 - 9/25 = 16/25, sin θ = 4/5', 'medium', 3, 30),
('nsmq_math_r1_021', 'subj_math', 'What is the equation of a circle with center (2, -3) and radius 5?', 'multiple_choice', 'round_one', '["A. (x-2)² + (y+3)² = 25", "B. (x+2)² + (y-3)² = 25", "C. (x-2)² + (y-3)² = 5", "D. (x+2)² + (y+3)² = 25"]', 'A', 'Circle equation: (x-h)² + (y-k)² = r², so (x-2)² + (y+3)² = 25', 'medium', 3, 30),
('nsmq_math_r1_022', 'subj_math', 'What is 2⁵ × 2³?', 'multiple_choice', 'round_one', '["A. 2⁸", "B. 2¹⁵", "C. 4⁸", "D. 2²"]', 'A', 'When multiplying with same base, add exponents: 2⁵⁺³ = 2⁸', 'easy', 3, 30),
('nsmq_math_r1_023', 'subj_math', 'What is the quadratic formula for ax² + bx + c = 0?', 'multiple_choice', 'round_one', '["A. x = (-b ± √(b²-4ac))/2a", "B. x = (b ± √(b²-4ac))/2a", "C. x = (-b ± √(b²+4ac))/2a", "D. x = (-b ± √(4ac-b²))/2a"]', 'A', 'The quadratic formula is x = (-b ± √(b²-4ac))/2a', 'easy', 3, 30),
('nsmq_math_r1_024', 'subj_math', 'If log₂(x) = 5, what is x?', 'multiple_choice', 'round_one', '["A. 10", "B. 25", "C. 32", "D. 64"]', 'C', 'log₂(x) = 5 means x = 2⁵ = 32', 'easy', 3, 30),
('nsmq_math_r1_025', 'subj_math', 'What is the range of f(x) = x² for all real x?', 'multiple_choice', 'round_one', '["A. All real numbers", "B. x ≥ 0", "C. x > 0", "D. x ≤ 0"]', 'B', 'Since x² is always non-negative, the range is y ≥ 0', 'medium', 3, 30),
('nsmq_math_r1_026', 'subj_math', 'How many sides does a dodecagon have?', 'multiple_choice', 'round_one', '["A. 8", "B. 10", "C. 12", "D. 14"]', 'C', 'A dodecagon has 12 sides', 'easy', 3, 30),
('nsmq_math_r1_027', 'subj_math', 'What is the volume of a cube with side length 4 cm?', 'multiple_choice', 'round_one', '["A. 16 cm³", "B. 48 cm³", "C. 64 cm³", "D. 96 cm³"]', 'C', 'Volume = s³ = 4³ = 64 cm³', 'easy', 3, 30),
('nsmq_math_r1_028', 'subj_math', 'What is the median of 3, 7, 9, 12, 15?', 'multiple_choice', 'round_one', '["A. 7", "B. 9", "C. 9.2", "D. 12"]', 'B', 'The median is the middle value when arranged in order: 9', 'easy', 3, 30),
('nsmq_math_r1_029', 'subj_math', 'Simplify: (x³)⁴', 'multiple_choice', 'round_one', '["A. x⁷", "B. x¹²", "C. x⁸¹", "D. 4x³"]', 'B', 'When raising a power to a power, multiply exponents: x³ˣ⁴ = x¹²', 'easy', 3, 30),
('nsmq_math_r1_030', 'subj_math', 'What is the value of tan 45°?', 'multiple_choice', 'round_one', '["A. 0", "B. 1/2", "C. 1", "D. √2"]', 'C', 'tan 45° = sin 45°/cos 45° = 1', 'easy', 3, 30),

-- PHYSICS Round One (30 questions)
('nsmq_phy_r1_001', 'subj_physics', 'What is the SI unit of electric current?', 'multiple_choice', 'round_one', '["A. Volt", "B. Ohm", "C. Ampere", "D. Watt"]', 'C', 'The SI unit of electric current is the Ampere (A)', 'easy', 3, 30),
