('nsmq_phy_r1_007', 'subj_physics', 'What is the speed of light in vacuum?', 'multiple_choice', 'round_one', '["A. 3 × 10⁶ m/s", "B. 3 × 10⁷ m/s", "C. 3 × 10⁸ m/s", "D. 3 × 10⁹ m/s"]', 'C', 'The speed of light in vacuum is approximately 3 × 10⁸ m/s', 'easy', 3, 30),
('nsmq_phy_r1_008', 'subj_physics', 'What is Ohm''s Law?', 'multiple_choice', 'round_one', '["A. V = IR", "B. V = I/R", "C. V = R/I", "D. I = VR"]', 'A', 'Ohm''s Law states V = IR (Voltage = Current × Resistance)', 'easy', 3, 30),
('nsmq_phy_r1_009', 'subj_physics', 'What is the unit of frequency?', 'multiple_choice', 'round_one', '["A. Second", "B. Hertz", "C. Meter", "D. Newton"]', 'B', 'The SI unit of frequency is Hertz (Hz)', 'easy', 3, 30),
('nsmq_phy_r1_010', 'subj_physics', 'Which law states that every action has an equal and opposite reaction?', 'multiple_choice', 'round_one', '["A. Newton''s First Law", "B. Newton''s Second Law", "C. Newton''s Third Law", "D. Law of Conservation of Energy"]', 'C', 'Newton''s Third Law of Motion states this principle', 'easy', 3, 30),
('nsmq_phy_r1_011', 'subj_physics', 'What is the relationship between wavelength (λ) and frequency (f) of a wave?', 'multiple_choice', 'round_one', '["A. v = λf", "B. v = λ/f", "C. v = f/λ", "D. λ = vf"]', 'A', 'Wave velocity = wavelength × frequency (v = λf)', 'medium', 3, 30),
