('nsmq_phy_r1_013', 'subj_physics', 'What is the total resistance when two 10Ω resistors are connected in parallel?', 'multiple_choice', 'round_one', '["A. 5Ω", "B. 10Ω", "C. 20Ω", "D. 100Ω"]', 'A', '1/R = 1/10 + 1/10 = 2/10, R = 5Ω', 'medium', 3, 30),
('nsmq_phy_r1_014', 'subj_physics', 'Which electromagnetic wave has the highest frequency?', 'multiple_choice', 'round_one', '["A. Radio waves", "B. Microwaves", "C. X-rays", "D. Gamma rays"]', 'D', 'Gamma rays have the highest frequency in the electromagnetic spectrum', 'easy', 3, 30),
('nsmq_phy_r1_015', 'subj_physics', 'What is the unit of power?', 'multiple_choice', 'round_one', '["A. Joule", "B. Newton", "C. Watt", "D. Pascal"]', 'C', 'The SI unit of power is the Watt (W)', 'easy', 3, 30),
('nsmq_phy_r1_016', 'subj_physics', 'A car travels 100 km in 2 hours. What is its average speed?', 'multiple_choice', 'round_one', '["A. 25 km/h", "B. 50 km/h", "C. 100 km/h", "D. 200 km/h"]', 'B', 'Average speed = distance/time = 100/2 = 50 km/h', 'easy', 3, 30),
('nsmq_phy_r1_017', 'subj_physics', 'What happens to the resistance of a conductor when its temperature increases?', 'multiple_choice', 'round_one', '["A. Decreases", "B. Increases", "C. Remains same", "D. Becomes zero"]', 'B', 'For most conductors, resistance increases with temperature', 'medium', 3, 30),
('nsmq_phy_r1_018', 'subj_physics', 'What is the phenomenon of splitting white light into its component colors called?', 'multiple_choice', 'round_one', '["A. Reflection", "B. Refraction", "C. Dispersion", "D. Diffraction"]', 'C', 'Dispersion is the splitting of white light into spectrum colors', 'easy', 3, 30),
('nsmq_phy_r1_019', 'subj_physics', 'What is the work done when a force of 10 N moves an object 5 m in the direction of the force?', 'multiple_choice', 'round_one', '["A. 2 J", "B. 15 J", "C. 50 J", "D. 500 J"]', 'C', 'Work = Force × Distance = 10 × 5 = 50 J', 'easy', 3, 30),
('nsmq_phy_r1_020', 'subj_physics', 'Which instrument is used to measure atmospheric pressure?', 'multiple_choice', 'round_one', '["A. Thermometer", "B. Barometer", "C. Hygrometer", "D. Ammeter"]', 'B', 'A barometer is used to measure atmospheric pressure', 'easy', 3, 30),
('nsmq_phy_r1_021', 'subj_physics', 'What is the principle of conservation of momentum?', 'multiple_choice', 'round_one', '["A. Momentum is always increasing", "B. Momentum is always decreasing", "C. Total momentum before collision equals total momentum after", "D. Momentum depends on position"]', 'C', 'In a closed system, total momentum before = total momentum after collision', 'medium', 3, 30),
('nsmq_phy_r1_022', 'subj_physics', 'What type of energy does a compressed spring have?', 'multiple_choice', 'round_one', '["A. Kinetic energy", "B. Potential energy", "C. Thermal energy", "D. Nuclear energy"]', 'B', 'A compressed spring stores elastic potential energy', 'easy', 3, 30),
('nsmq_phy_r1_023', 'subj_physics', 'What is the focal length of a plane mirror?', 'multiple_choice', 'round_one', '["A. Zero", "B. Infinity", "C. 1 meter", "D. Depends on size"]', 'B', 'A plane mirror has infinite focal length (parallel rays remain parallel)', 'medium', 3, 30),
